test('SYNTHETIC mixed-pool delivery propagates first-availability baseline markers without duplicate-time inflation',async()=>{
 const boost=JSON.parse(readFileSync('evidence/protocol-pool-effects-20261028/boost-actual.json','utf8')),other={mint:'5TdjfgA5eJUFD4xQp8ZRvtZAQZVXZHq1dtB4pEg8pump',pool:'5ALPjDC4WUfReszwbmZLpwwbvfyqbjWgJw4t4K6LvE2k',minSlot:boost.slot},opened=Math.floor(boost.blockTime*1000/10000)*10000-10000,f=setup({dataContract:CONFIRMED_PROGRAM_ACTIVITY_V3_SHADOW,maximumCandidates:2,at:opened,slot:boost.slot}),socket=await f.open();await f.flow.addCandidate(other);await f.drive(8);await f.advance(boost.blockTime*1000-f.now);
 const ordinary=clone(tx.meta.logMessages) as string[];for(let i=0;i<ordinary.length;i++){if(!ordinary[i]!.startsWith('Program data: '))continue;const bytes=ordinary[i]!.slice(14),event=coder.events.decode(bytes);if(!event||!['BuyEvent','SellEvent'].includes(event.name))continue;const e=event.data as any;e.timestamp=new BN(boost.blockTime);ordinary[i]='Program data: '+Buffer.concat([Buffer.from(bytes,'base64').subarray(0,8),coder.types.encode(event.name,e)]).toString('base64');}
 const value={signature:bs58.encode(Buffer.alloc(64,178)),err:null,logs:[...ordinary,...boost.meta.logMessages]},notice=(mint:string)=>({jsonrpc:'2.0',method:'logsNotification',params:{subscription:f.flow.snapshot(mint)!.subscription,result:{context:{slot:boost.slot},value}}});socket.frame(notice(scope.mint));assert.equal(f.flow.protocolEffectLedger(other.mint).length,1);const shared=f.flow.notificationLedger(other.mint)[0]!;assert.equal(shared.scopeEvidence,'confirmed-transaction-program-frame');assert.equal(shared.deliveredByMint,scope.mint);assert.equal(shared.observedForMint,other.mint);assert.equal(shared.parsedEvents,0);assert.equal(shared.eventsAccepted,0);assert.equal(shared.protocolEffects,1);socket.frame(notice(other.mint));assert.equal(f.flow.usage().protocolEffects,1);assert.equal(f.flow.protocolEffectLedger(other.mint).length,1);
 for(const elapsed of [20000,40000,60000]){await f.advance(opened+elapsed-f.now);f.flow.requestSupportRefresh();await f.drive();}for(const mint of [scope.mint,other.mint])assert.equal(f.flow.snapshot(mint)!.strictV2Unavailable,true,'both actually associated scopes inherit whole-transaction baseline unavailability');const audit=await auditNativeFlowWindow({pool:other.pool,notifications:f.flow.notificationLedger(other.mint),target:{startAt:opened,endAt:opened+60000},contextFences:{lower:{slot:boost.slot-1,availableAt:opened,bankClockAt:opened},upper:{slot:boost.slot+1,availableAt:f.now,bankClockAt:f.now}},maximumPages:1,pageLimit:1000,now:()=>f.now,call:async<T>(_method:string,params:unknown[])=>{assert.equal((params[1] as any).minContextSlot,boost.slot+1);return [{signature:value.signature,slot:boost.slot,err:null,blockTime:boost.blockTime,confirmationStatus:'confirmed'},{signature:bs58.encode(Buffer.alloc(64,179)),slot:boost.slot-2,err:null,blockTime:Math.floor(opened/1000)-1,confirmationStatus:'confirmed'}] as T;}});assert.equal(audit.status,'verified','synthetic independent history can verify the genuinely captured cross-scope identity without inventing a second subscription delivery');assert.equal(audit.requiredSignatures.length,1);
 for(const elapsed of [80000,100000,120000,140000]){await f.advance(opened+elapsed-f.now);f.flow.requestSupportRefresh();await f.drive();}socket.frame(notice(other.mint));for(const mint of [scope.mint,other.mint])assert.equal(f.flow.snapshot(mint)!.strictV2Unavailable,false,'identical late duplicate cannot move an old protocol effect into a new window');assert.equal(f.flow.usage().protocolEffects,1);assert.equal(f.gaps.length,0);await f.flow.stop();
});


/** A synthetic capacity replay uses the measured 66.893-second overload duration,
 * unique signatures and failed/nontrade records. It tests bounded bookkeeping
 * and exact audit mechanics, never natural trading or historical profitability. */
test('SYNTHETIC 4097 unique notices over the measured overload duration retain the full closed window and partial bucket',async()=>{
 const aligned=Math.floor((retained.data.rpcAvailableAt as number)/10000)*10000,opened=aligned+7803,f=setup({at:opened}),socket=await f.open(),subscription=f.flow.snapshot(scope.mint)!.subscription!,all:Array<{signature:string;slot:number;at:number}>=[];
 const unique=(n:number)=>{const bytes=Buffer.alloc(64,146);bytes.writeUInt32LE(n,0);return bs58.encode(bytes);};let nextSupport=opened+20000;
 for(let i=0;i<4097;i++){
  const at=opened+Math.floor(i*66893/4096);await f.advance(at-f.now);if(at>=nextSupport){f.flow.requestSupportRefresh();await f.drive();nextSupport=at+20000;}
  const row={signature:unique(i+1),slot:tx.slot+i+1,at};all.push(row);socket.frame({jsonrpc:'2.0',method:'logsNotification',params:{subscription,result:{context:{slot:row.slot},value:{signature:row.signature,err:{InstructionError:[1,{Custom:1}]},logs:[]}}}});
 }
 const view=f.flow.snapshot(scope.mint)!,ledger=f.flow.notificationLedger(scope.mint),start=Math.floor(f.now/10000)*10000-60000,end=start+60000,required=all.filter(n=>n.at>=start),pre=all.filter(n=>n.at<start).at(-1)!;
 assert.equal(f.flow.usage().notifications,4097);assert.equal(f.flow.usage().duplicates,0);assert.equal(f.flow.usage().fatal,null);assert.equal(view.hasQualityLoss,false);assert.equal(view.warm,true);assert.equal(view.notificationRetention.maximumRows,8192);assert.ok(view.notificationRetention.compactedRows>0);assert.ok(ledger.length<4096,'real prewindow-slot compaction avoids the old global-stop boundary');assert.deepEqual(ledger.map(n=>n.signature),[pre.signature,...required.map(n=>n.signature)]);assert.ok(ledger.some(n=>n.availableAt>=end),'the current partial bucket is retained for its later decision');assert.deepEqual(view.notificationRetention.fence,{signature:pre.signature,slot:pre.slot,availableAt:pre.at,windowStartAt:start});
 for(const row of ledger){assert.equal(row.subscriptionMint,scope.mint);assert.equal(row.subscriptionPool,scope.pool);assert.equal(row.subscriptionId,subscription);assert.equal(row.connectionId,1);}
 // Independently returned synthetic history spans the real retained lower fence.
 // Four pages are deliberately required; this is not a one-page capacity claim.
 let pages=0;const history=[...all].reverse(),audit=await auditNativeFlowWindow({pool:scope.pool,notifications:ledger,target:{startAt:start,endAt:end},contextFences:{lower:{slot:tx.slot,availableAt:opened,bankClockAt:Math.floor(opened/1000)*1000},upper:{slot:all.at(-1)!.slot+1,availableAt:f.now,bankClockAt:Math.floor(f.now/1000)*1000}},maximumPages:4,pageLimit:1000,now:()=>f.now,call:async<T>(_method:string,params:unknown[])=>{const query=params[1] as {before?:string;limit:number},offset=query.before?history.findIndex(n=>n.signature===query.before)+1:0;pages++;return history.slice(offset,offset+query.limit).map(n=>({signature:n.signature,slot:n.slot,err:{InstructionError:[1,{Custom:1}]},blockTime:Math.floor(n.at/1000),confirmationStatus:'confirmed'})) as T;}});
 assert.equal(audit.status,'verified',audit.reason);assert.equal(pages,4);assert.deepEqual(new Set(audit.requiredSignatures),new Set(all.filter(n=>n.at>=start&&n.at<end).map(n=>n.signature)));assert.equal(audit.missingNotifications.length,0);assert.equal(f.records.filter(r=>r.kind==='native-flow-validated-events').length,4097,'append-only required packet evidence is not compacted or sampled');assert.equal(f.controlBytes,socket._socket.bytesRead);await f.flow.stop();
});

test('bounded per-candidate ledger overflow preserves the actual refusal without a second throw or loss of another scope',async()=>{
 const f=setup({maximumCandidates:2,maximumNotificationsPerCandidate:16}),socket=await f.open(),mint=new PublicKey(Buffer.alloc(32,147)),second={mint:mint.toBase58(),pool:canonicalPumpPoolPda(mint).toBase58(),minSlot:0};await f.open(second);const firstSubscription=f.flow.snapshot(scope.mint)!.subscription!,secondSubscription=f.flow.snapshot(second.mint)!.subscription!,send=(subscription:number,n:number)=>{const bytes=Buffer.alloc(64,148);bytes.writeUInt32LE(n,0);const signature=bs58.encode(bytes);socket.frame({jsonrpc:'2.0',method:'logsNotification',params:{subscription,result:{context:{slot:tx.slot+n},value:{signature,err:{InstructionError:[1,{Custom:1}]},logs:[]}}}});return signature;};
 for(let i=1;i<=16;i++)send(firstSubscription,i);const offender=send(firstSubscription,17),hot=f.flow.snapshot(scope.mint)!,rows=f.flow.notificationLedger(scope.mint);
 assert.equal(f.flow.usage().fatal,null);assert.equal(socket.readyState,WebSocket.OPEN);assert.equal(hot.suspended,true);assert.equal(hot.warm,false);assert.equal(hot.lastGapReason,'NATIVE_FLOW_NOTIFICATION_LEDGER_LIMIT');assert.equal(hot.notificationRetention.rows,16);assert.equal(hot.notificationRetention.capacityRefusal,true);assert.equal(rows.length,17,'one separate bounded refusal reserve preserves the actual offending notification');assert.equal(rows.at(-1)!.signature,offender);assert.equal(rows.at(-1)!.classification,'unusable');assert.equal(rows.at(-1)!.reason,'NATIVE_FLOW_NOTIFICATION_LEDGER_LIMIT');assert.equal(rows.at(-1)!.subscriptionMint,scope.mint);assert.equal(rows.at(-1)!.subscriptionPool,scope.pool);assert.equal(rows.at(-1)!.subscriptionId,firstSubscription);assert.equal(rows.at(-1)!.connectionId,1);
 const refusal=f.records.find(r=>r.kind==='native-flow-ledger-capacity-refusal')!;assert.equal(refusal.data.candidateLocal,true);assert.equal(refusal.data.validatedPacketRetained,true);assert.equal(refusal.data.allReceivedBytesStillAccounted,true);assert.equal(f.records.filter(r=>r.kind==='native-flow-validated-events').length,17);assert.ok(f.records.some(r=>r.kind==='native-flow-refusal'&&r.data.signature===offender));
 const healthy=send(secondSubscription,100);assert.equal(f.flow.snapshot(second.mint)!.hasQualityLoss,false);assert.equal(f.flow.snapshot(second.mint)!.suspended,false);assert.equal(f.flow.notificationLedger(second.mint).at(-1)!.signature,healthy);assert.equal(f.flow.usage().fatal,null);assert.equal(f.controlBytes,socket._socket.bytesRead);await f.flow.stop();
});

