 const f=setup({maximumCandidates:2}),socket=await f.open(),mint=new PublicKey(Buffer.alloc(32,149)),second={mint:mint.toBase58(),pool:canonicalPumpPoolPda(mint).toBase58(),minSlot:0};await f.open(second);const firstSubscription=f.flow.snapshot(scope.mint)!.subscription!,secondSubscription=f.flow.snapshot(second.mint)!.subscription!,unique=(n:number)=>{const bytes=Buffer.alloc(64,150);bytes.writeUInt32LE(n,0);return bs58.encode(bytes);},send=(subscription:number,n:number,custom=1)=>socket.frame({jsonrpc:'2.0',method:'logsNotification',params:{subscription,result:{context:{slot:tx.slot+n},value:{signature:unique(n),err:{InstructionError:[1,{Custom:custom}]},logs:[]}}}});
 for(let i=1;i<=8193;i++)send(i%2?firstSubscription:secondSubscription,i);assert.equal(f.flow.usage().notifications,8193);assert.equal(f.flow.usage().fatal,null);assert.equal(f.flow.usage().duplicates,0);assert.equal(f.flow.snapshot(scope.mint)!.hasQualityLoss,false);assert.equal(f.flow.snapshot(second.mint)!.hasQualityLoss,false);assert.equal(f.flow.notificationLedger(scope.mint).length,4097);assert.equal(f.flow.notificationLedger(second.mint).length,4096);
 send(firstSubscription,1,2);assert.equal(f.flow.usage().corrections,1,'the earliest identity is still checked inside the unchanged180-second correction horizon');assert.equal(f.flow.snapshot(scope.mint)!.lastGapReason,'NATIVE_FLOW_CONFIRMED_CORRECTION');assert.equal(f.flow.snapshot(second.mint)!.hasQualityLoss,false);assert.equal(f.flow.usage().fatal,null);assert.equal(f.controlBytes,socket._socket.bytesRead);await f.flow.stop();
