// This is actual retained event bytes in a controlled fresh-support transport.
// It does not retroactively repair the original forward window.
test('native support forwards its validated base mint owner into classic protocol effect decoding',async()=>{
 const evidence=JSON.parse(readFileSync('evidence/classic-protocol-burn-20261028/actual-refusal-and-support.json','utf8')),raw=evidence.actualRawRefusal.data,support=evidence.freshSupport.data;
 for(const [baseTokenProgram,expected] of [[support.summary.tokenProgram,'accepted'],[undefined,'LOG_NATIVE_PROTOCOL_BASE_BURN_FRAME'],['TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb','LOG_NATIVE_PROTOCOL_BASE_TOKEN_PROGRAM_MISMATCH']] as const){
  const f=setup({baseTokenProgram,dataContract:CONFIRMED_PROGRAM_ACTIVITY_V3_SHADOW,at:raw.receivedAt,slot:raw.slot}),socket=await f.open({mint:support.mint,pool:support.pool,minSlot:raw.slot});
  socket.frame({jsonrpc:'2.0',method:'logsNotification',params:{subscription:f.flow.snapshot(support.mint)!.subscription,result:{context:{slot:raw.slot},value:{signature:raw.signature,err:null,logs:structuredClone(raw.logs)}}}});
  assert.equal(f.trades.length,0,'protocol burn never creates an ordinary buyer or trade');
  if(expected==='accepted'){assert.equal(f.gaps.length,0);assert.equal(f.flow.usage().protocolEffects,1);assert.equal(f.flow.protocolEffectLedger(support.mint)[0]!.quoteLamportsIn,'448404891');assert.equal(f.flow.notificationLedger(support.mint).at(-1)!.strictV2Unavailable,true,'actual protocol notification is marked; no claim about an earlier closed feature window');}
  else{assert.equal(f.flow.usage().protocolEffects,0);assert.ok(f.gaps.some(r=>r.reason===expected),JSON.stringify(f.gaps));}
  await f.flow.stop();
 }
});
